import{_ as e,o as l,c as i,a4 as r}from"./chunks/framework.2-Vke5-n.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"Slack<wbr>利用ガイドライン","tagline":"Slack Usage Guidelines","actions":[{"theme":"brand","text":"Slack利用ガイドライン","link":"./slack_usage_guidelines.md"}]}},"headers":[],"relativePath":"documents/forSlack/index.md","filePath":"documents/forSlack/index.md"}'),t={name:"documents/forSlack/index.md"};function c(s,a,o,n,d,u){return l(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>リモートワーク / ハイブリッドワーク前提の業務において、チャットなどの非同期コミュニケーションを円滑に進めることは、業務効率を向上させるだけではなく従業員全員の満足度を向上させ、より良い職場づくりに繋げることができる。</p><p>また、ユーザーの様々な要望に応えるため、現代のチャットサービスは豊富な機能が提供されている。しかし、各ユーザーの考え方 / 利用者の感覚が千差万別であるため、ある人によって問題ないとされる行動が、別の人にとっては良くない受け取り方をされることも多い。例えば次のような対立が考えられる。</p><ul><li>必要最低限の簡潔なメッセージを送る方が効率的だ / 文面が冷たくならないように絵文字や感嘆符（！）を使うべきだ</li><li>質問はDMで行うべき / チャンネルで行うべき</li><li>times（分報）チャンネルを活用すべき / ノイズなので個人のメモに閉じるべき</li></ul><p>これら運用方法は利用者の所属する部署やチームごとに自然と決めていくことが多いが、複数のチャンネルで異なった運用方針である場合に混乱をきたすことがしばしばである。また、トレードオフを理解せずに、メールのコミュニケーションモデルを引きずった方針を取ってしまうこともある。異なる文化圏のチームから移籍した時に、ハレーションが起きるケースも多い。</p><p>本ガイドラインはSlackを対象に利用方針についてのベースとなる規約を設け、Slackを用いてより良いコミュニケーションを促進することを目的とする。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h2><ul><li>一般ユーザー視点での利活用を中心とする</li><li>次のような特に管理者が関心を持つ事項については対象外とする <ul><li>パスワードポリシー / 多要素認証の強制</li><li>社外メンバー招待 / ゲストレベルの調整</li><li>監査</li></ul></li></ul><p>また、以下の前提とする。</p><ul><li>自社のセキュリティポリシーや外部サービス利用ポリシーがある場合は、そちらを優先する</li><li>Slack Enterprise Grid / Google Workspaceを利用しているため、それらの機能を前提とする</li></ul><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、谷村元気、小澤泰河、村田靖拓、小橋昌明</li><li><strong>レビュアー</strong>: 清水雄一郎、後藤玲雄、八木雅斗、高瀬陸、板橋勇輝、壷屋翔</li></ul><p>また、本ガイドラインの策定にあたっては、すでにインターネットに公開されているSlack利用ガイドラインや記事等も参照させていただいた。</p><div class="info custom-block"><p class="custom-block-title">参考</p><p><a href="https://careers.mercari.com/mercan/articles/23325/" target="_blank" rel="noreferrer">メルカリ社内Slack利用ガイドラインを一挙公開しました〜！！#メルカリな日々</a> | <a href="https://github.com/mercari/mercari-slack-guidelines/blob/master/Slack_Guidelines_Ja.md" target="_blank" rel="noreferrer">mercari-Slack-guidelines/Slack_Guidelines_Ja.md</a></p></div><p>本ガイドラインが皆様のSlack活用をより快適にする一助となれば幸いである。</p><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.04.02 <a href="https://future-architect.github.io/articles/20250402a/" target="_blank" rel="noreferrer">Slack利用ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./slack_usage_guidelines.html">Slack利用ガイドライン</a></p></div>',20)])])}const m=e(t,[["render",c]]);export{h as __pageData,m as default};
